private get<T>(
    baseUrl: string,
    path: string,
    responseSchema: z.ZodType<T>,
    values: Record<string, unknown> = {},
  ) {
    const params = Object.fromEntries(
      Object.entries(values)
        .filter(([, v]) => v !== undefined)
        .map(([k, v]) => [k, String(v)]),
    );
    return request({
      method: 'GET',
      baseUrl,
      path,
      params,
      responseSchema,
      auth: this.auth,
      numRetries: this.numRetries,
      omitDebugBody: true,
    });
  }

