    closed = true;
    signal.removeEventListener('abort', onAbort);
    // A misbehaving cancel hook must not park a CLI or delay deadline cleanup.
    void reader.cancel(reason).catch(() => {});
    reader.releaseLock();
    buffer = '';
    data = [];
    dispose();
  };
