export function generateWorkspaceScopeName(workspaceName: string): string {
  const stem = workspaceName
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '_')
    .replace(/^_+|_+$/g, '');
  // node:crypto, not globalThis.crypto: the Web Crypto global is absent on Node 18 (engines >=18).
  let suffix = '';
  for (const byte of randomBytes(SUFFIX_LENGTH))
    suffix += SUFFIX_ALPHABET[byte % SUFFIX_ALPHABET.length];
  return `ws_${stem || 'workspace'}_${suffix}`;
}

function messageOf(err: unknown): string {
  return err instanceof Error ? err.message : String(err);
}

function statusOf(err: unknown): { statusCode?: number } {
  const status = (err as { statusCode?: unknown }).statusCode;
  return typeof status === 'number' ? { statusCode: status } : {};
}

