    return request({
      method: 'GET',
      baseUrl: globalConfiguration.apiEndpoint,
      path: SCAN_REPORTS_PATH,
      timeoutMs: opts.timeoutMs,
      signal: opts.signal,
      params: { report_ids: reportIds.join(',') },
      responseSchema: z.array(ThreatScanReportSchema),
      auth: this.buildAuth(),
      numRetries,
    });
  }

